              isSelected && 'scale-125 z-30'
            )}
          >
            {/* Chapa del Jugador */}
            <div
              className={clsx(
                'relative w-10 h-10 md:w-12 md:h-12 rounded-full flex items-center justify-center font-bold text-xs md:text-sm shadow-lg border-2 transition-all',
