import { Club, Player, MatchEvent } from '@/types/football-manager';

export interface LiveMatchState {
  id: string;
  season: number;
  round: number;
  homeClub: Club;
  awayClub: Club;
  homeScore: number;
  awayScore: number;
  minute: number;
  isFinished: boolean;
  isPaused: boolean;
  speedMultiplier: number; // 1, 2, 5
  ballPosition: { x: number; y: number }; // 0-100%
  attackingTeamId: string;
  events: MatchEvent[];
  homeStats: {
    possession: number;
    shots: number;
    shotsOnTarget: number;
    chances: number;
    fouls: number;
    corners: number;
  };
  awayStats: {
    possession: number;
    shots: number;
    shotsOnTarget: number;
    chances: number;
    fouls: number;
    corners: number;
  };
  homeSubsRemaining: number;
  awaySubsRemaining: number;
  homeLineup: string[]; // Current 11 on pitch
  awayLineup: string[]; // Current 11 on pitch
  homeBench: string[];
  awayBench: string[];
  playerRatings: Record<string, number>; // playerId -> 6.0 to 10.0
}

export function initLiveMatch(
  season: number,
  round: number,
  homeClub: Club,
  awayClub: Club
): LiveMatchState {
  const ratings: Record<string, number> = {};
  [...homeClub.startingXI, ...awayClub.startingXI].forEach((id) => {
    ratings[id] = 6.0;
  });

  return {
    id: `live-m-${season}-${round}-${Date.now()}`,
    season,
    round,
    homeClub: JSON.parse(JSON.stringify(homeClub)),
    awayClub: JSON.parse(JSON.stringify(awayClub)),
    homeScore: 0,
    awayScore: 0,
    minute: 0,
    isFinished: false,
    isPaused: false,
    speedMultiplier: 1,
    ballPosition: { x: 50, y: 50 },
    attackingTeamId: homeClub.id,
    events: [
      {
        minute: 0,
        type: 'commentary',
        teamId: homeClub.id,
        description: `¡Arranca el partido en el ${homeClub.stadiumName}! ${homeClub.name} vs ${awayClub.name}`,
        ballZone: { x: 50, y: 50 },
      },
    ],
    homeStats: {
      possession: 50,
      shots: 0,
      shotsOnTarget: 0,
      chances: 0,
      fouls: 0,
      corners: 0,
    },
    awayStats: {
      possession: 50,
      shots: 0,
      shotsOnTarget: 0,
      chances: 0,
      fouls: 0,
      corners: 0,
    },
    homeSubsRemaining: 5,
    awaySubsRemaining: 5,
    homeLineup: [...homeClub.startingXI],
    awayLineup: [...awayClub.startingXI],
    homeBench: [...homeClub.substitutes],
    awayBench: [...awayClub.substitutes],
    playerRatings: ratings,
  };
}

// Simulates 1 minute of match action
export function tickLiveMatch(
  match: LiveMatchState,
  allPlayersMap: Record<string, Player>
): LiveMatchState {
  if (match.isFinished) return match;

  const currentMinute = match.minute + 1;
  const next = { ...match, minute: currentMinute };

  // Calculate team strengths with tactical modifiers
  const homePlayers = match.homeLineup.map((id) => allPlayersMap[id]).filter(Boolean);
  const awayPlayers = match.awayLineup.map((id) => allPlayersMap[id]).filter(Boolean);

  const homeGk = homePlayers.find((p) => p.position === 'POR') || homePlayers[0];
  const awayGk = awayPlayers.find((p) => p.position === 'POR') || awayPlayers[0];

  const getTeamPwr = (players: Player[], ment: Club['mentalidad']) => {
    const avg = players.reduce((s, p) => s + p.overall, 0) / Math.max(1, players.length);
    let mod = 1.0;
    if (ment === 'ultra_ofensiva') mod = 1.15;
    else if (ment === 'ofensiva') mod = 1.07;
    else if (ment === 'muy_defensiva') mod = 0.85;
    return avg * mod;
  };

  const homePwr = getTeamPwr(homePlayers, match.homeClub.mentalidad) + 2.5; // Ventaja de local
  const awayPwr = getTeamPwr(awayPlayers, match.awayClub.mentalidad);

  // Who gets the ball this minute?
  const homeProb = homePwr / (homePwr + awayPwr);
  const isHomeAttack = Math.random() < homeProb;
  const attTeam = isHomeAttack ? match.homeClub : match.awayClub;
  const defTeam = isHomeAttack ? match.awayClub : match.homeClub;
  const attPlayers = isHomeAttack ? homePlayers : awayPlayers;
  const defPlayers = isHomeAttack ? awayPlayers : homePlayers;
  const defGk = isHomeAttack ? awayGk : homeGk;

  next.attackingTeamId = attTeam.id;

  // Move ball position across 2D pitch
  const targetX = isHomeAttack ? 55 + Math.random() * 40 : 45 - Math.random() * 40;
  const targetY = 15 + Math.random() * 70;
  next.ballPosition = { x: Math.round(targetX), y: Math.round(targetY) };

  // Update dynamic possession
  const totalMins = Math.max(1, currentMinute);
  const homeAttacks = next.events.filter((e) => e.teamId === match.homeClub.id).length + (isHomeAttack ? 1 : 0);
  const rawPoss = Math.round((homeAttacks / (totalMins + 10)) * 100);
  next.homeStats.possession = Math.max(35, Math.min(65, rawPoss));
  next.awayStats.possession = 100 - next.homeStats.possession;

  // Random event roll for this minute
  const roll = Math.random();

  // 1. CHANCE OF DANGEROUS SHOT (approx 12-15% of minutes)
  if (roll < 0.14) {
    const shooter = attPlayers.filter((p) => ['DC', 'EI', 'ED', 'MCO'].includes(p.position))[Math.floor(Math.random() * 4)] || attPlayers[0];
    const passer = attPlayers.filter((p) => p.id !== shooter?.id && ['MC', 'MCO', 'EI', 'ED'].includes(p.position))[0];

    const statsObj = isHomeAttack ? next.homeStats : next.awayStats;
    statsObj.shots += 1;

    // Check shooter weapon (Blue Lock weapon trigger!)
    const weapon = shooter?.weapons?.[0];
    let shotPower = (shooter?.stats.shooting || 75) + (weapon ? weapon.level * 0.15 : 0);
    let gkPower = (defGk?.stats.goalkeeping || 70) + (defGk?.weapons?.[0] ? defGk.weapons[0].level * 0.15 : 0);

    // Flow state bonus
    if (shooter?.egoRating && shooter.egoRating > 88 && Math.random() < 0.3) {
      shotPower += 15;
      next.events.unshift({
        minute: currentMinute,
        type: 'flow',
        teamId: attTeam.id,
        playerId: shooter.id,
        playerName: shooter.name,
        description: `⚡ ¡FLOW ACTIVADO! ${shooter.name} entra en trance egoísta y visualiza la trayectoria perfecta.`,
        ballZone: next.ballPosition,
      });
    }

    // Shot evaluation
    const isTarget = Math.random() < 0.65;
    if (isTarget) {
      statsObj.shotsOnTarget += 1;

      // Is it a GOAL?
      const goalThreshold = 0.42 * (shotPower / (shotPower + gkPower));
      if (Math.random() < goalThreshold) {
        // GOAL!
        statsObj.chances += 1;
        if (isHomeAttack) {
          next.homeScore += 1;
        } else {
          next.awayScore += 1;
        }

        // Increase rating for scorer
        if (shooter) {
          next.playerRatings[shooter.id] = Math.min(10, (next.playerRatings[shooter.id] || 6.0) + 1.2);
        }
        if (passer) {
          next.playerRatings[passer.id] = Math.min(10, (next.playerRatings[passer.id] || 6.0) + 0.6);
        }

        let goalDesc = `⚽ ¡GOOOOOOL DE ${attTeam.name.toUpperCase()}! (${currentMinute}') `;
        if (weapon) {
          goalDesc += `¡${shooter.name} ejecuta su ${weapon.name} sin piedad directo al fondo de la red!`;
        } else {
          goalDesc += `¡Definición inapelable de ${shooter?.name || 'delantero'} tras desmarque al espacio!`;
        }
        if (passer) {
          goalDesc += ` (Asistencia de ${passer.name})`;
        }

        next.events.unshift({
          minute: currentMinute,
          type: 'goal',
          teamId: attTeam.id,
          playerId: shooter?.id,
          playerName: shooter?.name,
          assistPlayerId: passer?.id,
          assistPlayerName: passer?.name,
          description: goalDesc,
          ballZone: { x: isHomeAttack ? 95 : 5, y: 50 },
        });
      } else {
        // SAVED BY GOALKEEPER
        if (defGk) {
          next.playerRatings[defGk.id] = Math.min(10, (next.playerRatings[defGk.id] || 6.0) + 0.4);
        }
        const gkWeapon = defGk?.weapons?.[0];
        let saveDesc = `🧤 ¡PARADÓN de ${defGk?.name || 'el portero'}! `;
        if (gkWeapon) {
          saveDesc += `Desvía el misil de ${shooter?.name} con su habilidad especial ${gkWeapon.name}.`;
        } else {
          saveDesc += `Ataja el disparo ajustado de ${shooter?.name} con reflejos felinos.`;
        }

        next.events.unshift({
          minute: currentMinute,
          type: 'save',
          teamId: defTeam.id,
          playerId: defGk?.id,
          playerName: defGk?.name,
          description: saveDesc,
          ballZone: { x: isHomeAttack ? 92 : 8, y: 50 },
        });

        // Corner chance
        if (Math.random() < 0.5) {
          statsObj.corners += 1;
        }
      }
    } else {
      // Off target shot
      next.events.unshift({
        minute: currentMinute,
        type: 'shot',
        teamId: attTeam.id,
        playerId: shooter?.id,
        playerName: shooter?.name,
        description: `Ocasión de ${shooter?.name}: remate potente que sale rozando el travesaño del ${defTeam.name}.`,
        ballZone: next.ballPosition,
      });
    }
  }
  // 2. FOUL OR CARD (approx 4%)
  else if (roll > 0.96) {
    const defender = defPlayers[Math.floor(Math.random() * defPlayers.length)];
    const defStats = isHomeAttack ? next.awayStats : next.homeStats;
    defStats.fouls += 1;

    const isCard = Math.random() < 0.35;
    if (isCard && defender) {
      next.playerRatings[defender.id] = Math.max(4.0, (next.playerRatings[defender.id] || 6.0) - 0.5);

      next.events.unshift({
        minute: currentMinute,
        type: 'yellow_card',
        teamId: defTeam.id,
        playerId: defender.id,
        playerName: defender.name,
        description: `🟨 Tarjeta amarilla para ${defender.name} por una entrada dura cortando el contragolpe.`,
        ballZone: next.ballPosition,
      });
    }
  }
  // 3. MIDFIELD DUELL / METAVISION TACTICAL DUEL (approx 5%)
  else if (roll > 0.85 && roll <= 0.90) {
    const midAtt = attPlayers.find((p) => p.weapons.some((w) => w.type === 'vision')) || attPlayers[0];
    const midDef = defPlayers.find((p) => p.weapons.some((w) => w.type === 'defense')) || defPlayers[0];

    if (midAtt) {
      next.events.unshift({
        minute: currentMinute,
        type: 'commentary',
        teamId: attTeam.id,
        playerId: midAtt.id,
        playerName: midAtt.name,
        description: `👀 ${midAtt.name} escanea el campo con visión periférica y filtra un pase rompiendo líneas defensivas.`,
        ballZone: next.ballPosition,
      });
    }
  }

  // Check full time
  if (currentMinute >= 90) {
    next.isFinished = true;
    next.events.unshift({
      minute: 90,
      type: 'commentary',
      teamId: match.homeClub.id,
      description: `🏁 ¡FINAL DEL PARTIDO! Marcador definitivo: ${match.homeClub.name} ${next.homeScore} - ${next.awayScore} ${match.awayClub.name}.`,
      ballZone: { x: 50, y: 50 },
    });
  }

  return next;
}

// In-match player substitution
export function executeLiveSub(
  match: LiveMatchState,
  isHome: boolean,
  playerOutId: string,
  playerInId: string,
  allPlayersMap: Record<string, Player>
): LiveMatchState {
  const currentSubs = isHome ? match.homeSubsRemaining : match.awaySubsRemaining;
  if (currentSubs <= 0) return match;

  const currentLineup = isHome ? [...match.homeLineup] : [...match.awayLineup];
  const currentBench = isHome ? [...match.homeBench] : [...match.awayBench];

  const outIdx = currentLineup.indexOf(playerOutId);
  const inIdx = currentBench.indexOf(playerInId);

  if (outIdx === -1 || inIdx === -1) return match;

  // Swap
  currentLineup[outIdx] = playerInId;
  currentBench[inIdx] = playerOutId;

  const pOut = allPlayersMap[playerOutId];
  const pIn = allPlayersMap[playerInId];
  const team = isHome ? match.homeClub : match.awayClub;

  const newRatings = { ...match.playerRatings };
  if (!newRatings[playerInId]) newRatings[playerInId] = 6.0;

  const newEvents = [
    {
      minute: match.minute,
      type: 'sub' as const,
      teamId: team.id,
      playerId: playerInId,
      playerName: pIn?.name || 'Jugador',
      description: `🔄 Cambio en ${team.name}: entra ${pIn?.name || 'suplente'} sustituyendo a ${pOut?.name || 'titular'}.`,
      ballZone: match.ballPosition,
    },
    ...match.events,
  ];

  return {
    ...match,
    homeLineup: isHome ? currentLineup : match.homeLineup,
    awayLineup: !isHome ? currentLineup : match.awayLineup,
    homeBench: isHome ? currentBench : match.homeBench,
    awayBench: !isHome ? currentBench : match.awayBench,
    homeSubsRemaining: isHome ? currentSubs - 1 : match.homeSubsRemaining,
    awaySubsRemaining: !isHome ? currentSubs - 1 : match.awaySubsRemaining,
    events: newEvents,
    playerRatings: newRatings,
  };
}

import seedrandom from 'seedrandom';
import { Player, Club, MatchEvent, Weapon } from '@/types/database';

export interface PlayerMatchStats {
  playerId: string;
  name: string;
  clubId: string;
  rating: number; // 1.0 to 10.0
  goals: number;
  assists: number;
  shots: number;
  shotsOnTarget: number;
  duelsTotal: number;
  duelsWon: number;
  saves: number;
  egoMeter: number; // 0 - 100
  flowActivated: boolean;
  chemicalReactionsCount: number;
  newBidYen: number;
  bidClubName?: string;
  bidCommentary?: string;
}

export interface SimulationResult {
  homeClub: Club;
  awayClub: Club;
  homeScore: number;
  awayScore: number;
  events: MatchEvent[];
  playerStats: Record<string, PlayerMatchStats>;
  summary: {
    manOfTheMatch: PlayerMatchStats;
    totalChemicalReactions: number;
    flowActivations: string[];
    bidsGenerated: Array<{
      playerName: string;
      biddingClub: string;
      offerYen: number;
      reason: string;
    }>;
  };
}

export interface MatchSimulationOptions {
  seed?: string | number;
  totalMinutes?: number; // defaults to 90
}

/**
 * Deterministic Blue Lock Match Simulator
 * Implements Turn-based Event Engine with:
 * - Weapon Calculation & Hierarchy (Metavision, Direct Shot, Kaiser Impact, Predator Eye)
 * - Dynamic Ego Meter & Flow State Activation
 * - Chemical Reaction Pairings
 * - NEL Yen Bid Valuation Algorithm
 */
export function simulateMatch(
  homeClub: Club,
  awayClub: Club,
  homePlayers: Player[],
  awayPlayers: Player[],
  options: MatchSimulationOptions = {}
): SimulationResult {
  const seed = options.seed ? String(options.seed) : `${homeClub.name}-vs-${awayClub.name}-week`;
  const rng = seedrandom(seed);

  const events: MatchEvent[] = [];
  let homeScore = 0;
  let awayScore = 0;

  // Initialize player match stats
  const playerStats: Record<string, PlayerMatchStats> = {};
  const allPlayers = [...homePlayers, ...awayPlayers];

  allPlayers.forEach((p) => {
    playerStats[p.id] = {
      playerId: p.id,
      name: p.name,
      clubId: p.club_id || '',
      rating: 6.0,
      goals: 0,
      assists: 0,
      shots: 0,
      shotsOnTarget: 0,
      duelsTotal: 0,
      duelsWon: 0,
      saves: 0,
      egoMeter: p.ego_rating || 50,
      flowActivated: false,
      chemicalReactionsCount: 0,
      newBidYen: p.market_value_yen,
    };
  });

  // Helper to get weapon of player
  const findWeapon = (p: Player, typeName: string): Weapon | undefined => {
    return p.weapons?.find(
      (w) =>
        w.name.toLowerCase().includes(typeName.toLowerCase()) ||
        w.type.toLowerCase().includes(typeName.toLowerCase())
    );
  };

  // Helper to pick a player from a team
  const pickPlayer = (team: Player[], positionFilter?: (pos: string) => boolean): Player => {
    const candidates = positionFilter ? team.filter((p) => positionFilter(p.position)) : team;
    const pool = candidates.length > 0 ? candidates : team;
    const idx = Math.floor(rng() * pool.length);
    return pool[idx];
  };

  // Check chemical reaction potential between two players
  const checkChemicalReaction = (p1: Player, p2: Player): { triggered: boolean; name: string; boost: number } => {
    if (!p1 || !p2 || p1.id === p2.id) return { triggered: false, name: '', boost: 0 };

    const w1 = p1.weapons.map((w) => w.name.toLowerCase());
    const w2 = p2.weapons.map((w) => w.name.toLowerCase());

    // Isagi (Metavision/Direct Shot) + Dribbler / Passer
    if (w1.some((w) => w.includes('metavision')) && w2.some((w) => w.includes('dribble') || w.includes('passer'))) {
      return { triggered: true, name: 'Spatial Resonance Overlap', boost: 25 };
    }
    // Kaiser Impact + Metavision pass
    if (w1.some((w) => w.includes('kaiser impact')) || w2.some((w) => w.includes('kaiser impact'))) {
      return { triggered: true, name: 'Emperor Rationality Drive', boost: 30 };
    }
    // Snuffy Tactics + Barou Predator Eye
    if (w1.some((w) => w.includes('tactics')) && w2.some((w) => w.includes('predator'))) {
      return { triggered: true, name: 'Anarchic King Infiltration', boost: 35 };
    }
    // Speed Burst + Curved Shot / Extreme Biomechanics
    if (w1.some((w) => w.includes('speed')) && w2.some((w) => w.includes('curved') || w.includes('biomechanics'))) {
      return { triggered: true, name: 'Supersonic Blitz Link', boost: 28 };
    }

    // Generic synergy if both have high ego
    if (p1.ego_rating > 85 && p2.ego_rating > 85 && rng() > 0.6) {
      return { triggered: true, name: 'Egoist Clashing Resonance', boost: 20 };
    }

    return { triggered: false, name: '', boost: 0 };
  };

  // Turn-based timeline: 10 key highlight turns over 90 minutes
  const totalTurns = 12;
  const minutes = [6, 14, 23, 35, 42, 51, 63, 72, 81, 88, 90, 93];

  for (let turn = 0; turn < totalTurns; turn++) {
    const minute = minutes[turn] || Math.floor((turn / totalTurns) * 90);

    // Decide attacking team based on club reputation and tactical style
    const homeWeight = homeClub.reputation + (rng() * 20 - 10);
    const awayWeight = awayClub.reputation + (rng() * 20 - 10);
    const attackingHome = homeWeight >= awayWeight;

    const attackingTeam = attackingHome ? homePlayers : awayPlayers;
    const defendingTeam = attackingHome ? awayPlayers : homePlayers;
    const attackingClub = attackingHome ? homeClub : awayClub;
    const defendingClub = attackingHome ? awayClub : homeClub;

    if (attackingTeam.length === 0 || defendingTeam.length === 0) continue;

    // Phase 1: Midfield Transition & Playmaking
    const playmaker = pickPlayer(attackingTeam, (pos) => ['CAM', 'CM', 'CDM', 'RW', 'LW', 'ST'].includes(pos));
    const primaryDefender = pickPlayer(defendingTeam, (pos) => ['CDM', 'CB', 'LB', 'RB', 'CM'].includes(pos));

    const playmakerStats = playerStats[playmaker.id];
    const defenderStats = playerStats[primaryDefender.id];

    playmakerStats.duelsTotal += 1;
    defenderStats.duelsTotal += 1;

    // Check Metavision or Playmaking weapons
    const metaVision = findWeapon(playmaker, 'metavision');
    const defenderMeta = findWeapon(primaryDefender, 'metavision');

    let attackerDuelScore = playmaker.stats.passing * 0.4 + playmaker.stats.dribbling * 0.4 + playmaker.ego_rating * 0.2;
    let defenderDuelScore = primaryDefender.stats.defense * 0.5 + primaryDefender.stats.physical * 0.3 + primaryDefender.ego_rating * 0.2;

    if (metaVision) {
      attackerDuelScore += (metaVision.level / 100) * 25;
      playmakerStats.egoMeter = Math.min(100, playmakerStats.egoMeter + 4);
    }
    if (defenderMeta) {
      defenderDuelScore += (defenderMeta.level / 100) * 22;
      defenderStats.egoMeter = Math.min(100, defenderStats.egoMeter + 3);
    }

    // Add randomness (form factor)
    attackerDuelScore += (rng() - 0.45) * 25;
    defenderDuelScore += (rng() - 0.45) * 25;

    const duelWonByAttacker = attackerDuelScore > defenderDuelScore;

    if (!duelWonByAttacker) {
      defenderStats.duelsWon += 1;
      defenderStats.rating = Math.min(10.0, defenderStats.rating + 0.3);
      events.push({
        minute,
        type: 'duel',
        description: `${primaryDefender.name} (${defendingClub.name}) reads the play perfectly with a surgical tackle, shutting down ${playmaker.name}'s build-up.`,
        player_id: primaryDefender.id,
        player_name: primaryDefender.name,
        secondary_player_id: playmaker.id,
        secondary_player_name: playmaker.name,
        ego_impact: 3,
      });
      continue;
    }

    // Duel won by attacker
    playmakerStats.duelsWon += 1;
    playmakerStats.rating = Math.min(10.0, playmakerStats.rating + 0.2);

    // Phase 2: Key Pass & Chemical Reaction Check
    const striker = pickPlayer(attackingTeam, (pos) => ['ST', 'CF', 'RW', 'LW'].includes(pos));
    const strikerStats = playerStats[striker.id];

    const chemicalReaction = checkChemicalReaction(playmaker, striker);
    let keyPassSuccess = true;

    if (chemicalReaction.triggered) {
      playmakerStats.chemicalReactionsCount += 1;
      strikerStats.chemicalReactionsCount += 1;
      playmakerStats.egoMeter = Math.min(100, playmakerStats.egoMeter + 8);
      strikerStats.egoMeter = Math.min(100, strikerStats.egoMeter + 10);

      events.push({
        minute,
        type: 'chemical_reaction',
        description: `⚡ CHEMICAL REACTION! [${chemicalReaction.name}] between ${playmaker.name} and ${striker.name}! The field coordinates synchronize instantly!`,
        player_id: striker.id,
        player_name: striker.name,
        secondary_player_id: playmaker.id,
        secondary_player_name: playmaker.name,
        ego_impact: 10,
      });
    }

    // Phase 3: Flow State Activation Check
    if (strikerStats.egoMeter >= 85 && !strikerStats.flowActivated && rng() > 0.35) {
      strikerStats.flowActivated = true;
      strikerStats.rating = Math.min(10.0, strikerStats.rating + 0.6);
      events.push({
        minute,
        type: 'flow_trigger',
        description: `🔥 FLOW STATE UNLOCKED! ${striker.name}'s eyes ignite with total egocentrism! Senses heighten to pure instinctual reflex!`,
        player_id: striker.id,
        player_name: striker.name,
        ego_impact: 15,
      });
    }

    // Phase 4: Shot Opportunity & Goalkeeper Duel
    strikerStats.shots += 1;
    const goalkeeper = defendingTeam.find((p) => p.position === 'GK') || pickPlayer(defendingTeam);
    const gkStats = playerStats[goalkeeper.id];

    // Calculate striking power & weapon bonus
    let shotPower = striker.stats.shooting * 0.5 + striker.overall * 0.3 + (strikerStats.flowActivated ? 25 : 0);
    const directShot = findWeapon(striker, 'direct shot');
    const kaiserImpact = findWeapon(striker, 'kaiser impact');
    const predatorEye = findWeapon(striker, 'predator eye');
    const curvedShot = findWeapon(striker, 'curved shot');
    const extremeBiomechanics = findWeapon(striker, 'extreme biomechanics');

    let weaponUsedName: string | undefined;

    if (kaiserImpact) {
      shotPower += 35;
      weaponUsedName = 'Kaiser Impact';
    } else if (directShot) {
      shotPower += 22;
      weaponUsedName = 'Direct Shot';
    } else if (predatorEye) {
      shotPower += 24;
      weaponUsedName = 'Predator Eye';
    } else if (curvedShot) {
      shotPower += 20;
      weaponUsedName = 'Curved Shot';
    } else if (extremeBiomechanics) {
      shotPower += 26;
      weaponUsedName = 'Extreme Biomechanics';
    }

    if (chemicalReaction.triggered) {
      shotPower += chemicalReaction.boost;
    }

    // Goalkeeper Defense
    const scorpionSaves = findWeapon(goalkeeper, 'scorpion saves');
    let gkSavePower = (goalkeeper.stats.defense || 80) * 0.6 + goalkeeper.overall * 0.3;
    if (scorpionSaves) {
      gkSavePower += 20;
    }
    gkSavePower += (rng() - 0.45) * 30;

    const isShotOnTarget = rng() > 0.15; // 85% on target in high-level match
    if (isShotOnTarget) {
      strikerStats.shotsOnTarget += 1;
    }

    if (isShotOnTarget && shotPower > gkSavePower) {
      // GOAL!
      if (attackingHome) {
        homeScore += 1;
      } else {
        awayScore += 1;
      }

      strikerStats.goals += 1;
      strikerStats.rating = Math.min(10.0, strikerStats.rating + 1.2);
      playmakerStats.assists += 1;
      playmakerStats.rating = Math.min(10.0, playmakerStats.rating + 0.7);

      const weaponPhrase = weaponUsedName ? ` unleashing weapon [${weaponUsedName}]` : '';
      events.push({
        minute,
        type: 'goal',
        description: `⚽ GOOOOOAL! ${striker.name} destroys the defensive line${weaponPhrase}! Set up by an exquisite ball from ${playmaker.name}. (${homeClub.name} ${homeScore} - ${awayScore} ${awayClub.name})`,
        player_id: striker.id,
        player_name: striker.name,
        secondary_player_id: playmaker.id,
        secondary_player_name: playmaker.name,
        weapon_used: weaponUsedName,
        ego_impact: 20,
      });
    } else if (isShotOnTarget) {
      // Saved by Goalkeeper!
      gkStats.saves += 1;
      gkStats.duelsWon += 1;
      gkStats.rating = Math.min(10.0, gkStats.rating + 0.5);
      const gkWeaponPhrase = scorpionSaves ? ` with an impossible [Scorpion Save]!` : ` with elite positional reflexes!`;
      events.push({
        minute,
        type: 'save',
        description: `🧤 SPECTACULAR SAVE! ${goalkeeper.name} stops ${striker.name}'s vicious strike${gkWeaponPhrase}`,
        player_id: goalkeeper.id,
        player_name: goalkeeper.name,
        secondary_player_id: striker.id,
        secondary_player_name: striker.name,
        ego_impact: 12,
      });
    } else {
      // Off target
      events.push({
        minute,
        type: 'duel',
        description: `${striker.name}'s ambitious effort misses just wide of the post under heavy pressure from the center backs.`,
        player_id: striker.id,
        player_name: striker.name,
        ego_impact: -2,
      });
    }
  }

  // Phase 5: Post-Match Valuation & NEL Auction Bids (in Yen ¥)
  const bidsGenerated: Array<{
    playerName: string;
    biddingClub: string;
    offerYen: number;
    reason: string;
  }> = [];

  const europeanClubs = [
    'Bastard München',
    'Paris X Gen',
    'Manshine City',
    'Ubers',
    'FC Barcha',
    'Real Madrid',
    'Arsenal FC',
  ];

  allPlayers.forEach((p) => {
    const stats = playerStats[p.id];
    let bidDeltaYen = 0;

    // Performance based bid calculation
    if (stats.goals > 0) {
      bidDeltaYen += stats.goals * 30000000; // ¥30,000,000 per goal
    }
    if (stats.assists > 0) {
      bidDeltaYen += stats.assists * 15000000; // ¥15,000,000 per assist
    }
    if (stats.duelsWon >= 3) {
      bidDeltaYen += 10000000; // ¥10,000,000 for duel dominance
    }
    if (stats.saves >= 2) {
      bidDeltaYen += stats.saves * 12000000; // ¥12,000,000 per key save
    }
    if (stats.flowActivated) {
      bidDeltaYen += 25000000; // ¥25,000,000 Flow hype premium
    }
    if (stats.chemicalReactionsCount > 0) {
      bidDeltaYen += stats.chemicalReactionsCount * 8000000;
    }

    // High rating multiplier
    if (stats.rating >= 8.5) {
      bidDeltaYen = Math.floor(bidDeltaYen * 1.35);
    } else if (stats.rating < 6.0) {
      bidDeltaYen = Math.max(-5000000, Math.floor(bidDeltaYen * 0.5));
    }

    const previousValue = p.market_value_yen || 10000000;
    stats.newBidYen = Math.max(10000000, previousValue + bidDeltaYen);

    // If impressive game, generate explicit European bid
    if (stats.goals > 0 || stats.assists > 0 || stats.rating >= 7.8 || stats.saves >= 2) {
      const interestedClubs = europeanClubs.filter((c) => c !== p.club_id);
      const chosenClub = interestedClubs[Math.floor(rng() * interestedClubs.length)] || 'Bastard München';
      stats.bidClubName = chosenClub;

      const reasons: string[] = [];
      if (stats.goals > 0) reasons.push(`${stats.goals} goal(s)`);
      if (stats.assists > 0) reasons.push(`${stats.assists} assist(s)`);
      if (stats.flowActivated) reasons.push('unlocked Flow state');
      if (stats.saves >= 2) reasons.push(`${stats.saves} decisive saves`);
      const reasonText = reasons.join(', ') || `Match rating of ${stats.rating.toFixed(1)}`;

      stats.bidCommentary = `${chosenClub} submits an annual wage offer of ¥${stats.newBidYen.toLocaleString()} after scouting: ${reasonText}.`;
      bidsGenerated.push({
        playerName: p.name,
        biddingClub: chosenClub,
        offerYen: stats.newBidYen,
        reason: reasonText,
      });
    }
  });

  // Pick Man of the Match
  let motm = Object.values(playerStats)[0];
  Object.values(playerStats).forEach((ps) => {
    if (ps.rating > motm.rating) {
      motm = ps;
    }
  });

  const totalChemicalReactions = Object.values(playerStats).reduce(
    (acc, ps) => acc + ps.chemicalReactionsCount,
    0
  );

  const flowActivations = Object.values(playerStats)
    .filter((ps) => ps.flowActivated)
    .map((ps) => ps.name);

  return {
    homeClub,
    awayClub,
    homeScore,
    awayScore,
    events,
    playerStats,
    summary: {
      manOfTheMatch: motm,
      totalChemicalReactions,
      flowActivations,
      bidsGenerated,
    },
  };
}

import { Club, Player, MatchFixture, LeagueTableRow, SeasonHistoryEntry } from '@/types/football-manager';

// Generates 22 rounds for 12 clubs using round-robin algorithm
export function generateSeasonFixtures(season: number, clubs: Club[]): MatchFixture[] {
  const n = clubs.length;
  const clubIds = clubs.map((c) => c.id);
  const rounds: MatchFixture[] = [];

  // Round robin for 11 rounds
  const tempIds = [...clubIds];
  const half = n / 2;

  const firstLegRounds: Array<Array<[string, string]>> = [];

  for (let r = 0; r < n - 1; r++) {
    const roundPairs: Array<[string, string]> = [];
    for (let i = 0; i < half; i++) {
      let home = tempIds[i];
      let away = tempIds[n - 1 - i];
      if ((i + r) % 2 === 1) {
        [home, away] = [away, home];
      }
      roundPairs.push([home, away]);
    }
    firstLegRounds.push(roundPairs);

    // Rotate array keeping first element fixed
    const last = tempIds.pop()!;
    tempIds.splice(1, 0, last);
  }

  // First leg (Jornadas 1 to 11)
  firstLegRounds.forEach((pairs, rIdx) => {
    const roundNum = rIdx + 1;
    pairs.forEach(([h, a], mIdx) => {
      rounds.push({
        id: `fix-s${season}-r${roundNum}-m${mIdx}`,
        season,
        round: roundNum,
        homeClubId: h,
        awayClubId: a,
        isPlayed: false,
      });
    });
  });

  // Second leg (Jornadas 12 to 22) - Inverted home/away
  firstLegRounds.forEach((pairs, rIdx) => {
    const roundNum = rIdx + 12;
    pairs.forEach(([h, a], mIdx) => {
      rounds.push({
        id: `fix-s${season}-r${roundNum}-m${mIdx}`,
        season,
        round: roundNum,
        homeClubId: a, // Inverted
        awayClubId: h,
        isPlayed: false,
      });
    });
  });

  return rounds;
}

// Simulates background AI matches for a round
export function simulateAiMatchesForRound(
  round: number,
  userClubId: string,
  fixtures: MatchFixture[],
  clubsMap: Record<string, Club>,
  players: Player[]
): { updatedFixtures: MatchFixture[]; updatedPlayers: Player[] } {
  const playersCopy = [...players];
  const fixturesCopy = [...fixtures];

  const roundFixtures = fixturesCopy.filter(
    (f) => f.round === round && !f.isPlayed && f.homeClubId !== userClubId && f.awayClubId !== userClubId
  );

  roundFixtures.forEach((fix) => {
    const hClub = clubsMap[fix.homeClubId];
    const aClub = clubsMap[fix.awayClubId];
    if (!hClub || !aClub) return;

    const hPwr = hClub.level + 2.5;
    const aPwr = aClub.level;

    // Realistic Poisson-like goals
    const hLambda = Math.max(0.4, (hPwr / aPwr) * 1.4);
    const aLambda = Math.max(0.3, (aPwr / hPwr) * 1.1);

    const calcGoals = (lambda: number) => {
      let g = 0;
      let p = Math.exp(-lambda);
      let f = p;
      const u = Math.random();
      while (u > f && g < 7) {
        g++;
        p = (p * lambda) / g;
        f += p;
      }
      return g;
    };

    const hScore = calcGoals(hLambda);
    const aScore = calcGoals(aLambda);

    fix.homeScore = hScore;
    fix.awayScore = aScore;
    fix.isPlayed = true;

    // Attribute goals and assists to top forwards/midfielders of AI clubs
    const hStrikers = playersCopy.filter((p) => p.clubId === hClub.id && ['DC', 'EI', 'ED'].includes(p.position));
    const aStrikers = playersCopy.filter((p) => p.clubId === aClub.id && ['DC', 'EI', 'ED'].includes(p.position));

    for (let i = 0; i < hScore; i++) {
      const scorer = hStrikers[Math.floor(Math.random() * hStrikers.length)];
      if (scorer) scorer.seasonGoals += 1;
    }
    for (let i = 0; i < aScore; i++) {
      const scorer = aStrikers[Math.floor(Math.random() * aStrikers.length)];
      if (scorer) scorer.seasonGoals += 1;
    }

    // Update match count
    playersCopy.filter((p) => p.clubId === hClub.id || p.clubId === aClub.id).forEach((p) => {
      p.seasonMatches += 1;
    });
  });

  return { updatedFixtures: fixturesCopy, updatedPlayers: playersCopy };
}

// Compute League Table sorted by Points, GD, GF
export function computeLeagueTable(clubs: Club[], fixtures: MatchFixture[]): LeagueTableRow[] {
  const tableMap: Record<string, LeagueTableRow> = {};

  clubs.forEach((c) => {
    tableMap[c.id] = {
      clubId: c.id,
      clubName: c.name,
      shortName: c.shortName,
      played: 0,
      won: 0,
      drawn: 0,
      lost: 0,
      goalsFor: 0,
      goalsAgainst: 0,
      goalDifference: 0,
      points: 0,
      formHistory: [],
    };
  });

  fixtures.filter((f) => f.isPlayed && f.homeScore !== undefined && f.awayScore !== undefined).forEach((f) => {
    const hRow = tableMap[f.homeClubId];
    const aRow = tableMap[f.awayClubId];
    if (!hRow || !aRow) return;

    const hs = f.homeScore!;
    const as = f.awayScore!;

    hRow.played += 1;
    aRow.played += 1;
    hRow.goalsFor += hs;
    hRow.goalsAgainst += as;
    aRow.goalsFor += as;
    aRow.goalsAgainst += hs;

    if (hs > as) {
      hRow.won += 1;
      hRow.points += 3;
      hRow.formHistory.push('W');
      aRow.lost += 1;
      aRow.formHistory.push('L');
    } else if (hs === as) {
      hRow.drawn += 1;
      hRow.points += 1;
      hRow.formHistory.push('D');
      aRow.drawn += 1;
      aRow.points += 1;
      aRow.formHistory.push('D');
    } else {
      hRow.lost += 1;
      hRow.formHistory.push('L');
      aRow.won += 1;
      aRow.points += 3;
      aRow.formHistory.push('W');
    }

    hRow.goalDifference = hRow.goalsFor - hRow.goalsAgainst;
    aRow.goalDifference = aRow.goalsFor - aRow.goalsAgainst;
  });

  return Object.values(tableMap).sort((a, b) => {
    if (b.points !== a.points) return b.points - a.points;
    if (b.goalDifference !== a.goalDifference) return b.goalDifference - a.goalDifference;
    return b.goalsFor - a.goalsFor;
  });
}

// End of season rollover
export function advanceToNextSeason(
  currentSeason: number,
  userClubId: string,
  clubs: Club[],
  players: Player[],
  table: LeagueTableRow[]
): {
  newSeason: number;
  newClubs: Club[];
  newPlayers: Player[];
  newFixtures: MatchFixture[];
  seasonHistoryEntry: SeasonHistoryEntry;
} {
  const userPos = table.findIndex((r) => r.clubId === userClubId) + 1;
  const champion = table[0];

  // Prize money according to final position
  const prizePool = [
    500000000, 380000000, 300000000, 240000000, 200000000, 160000000,
    130000000, 110000000, 90000000, 75000000, 60000000, 50000000
  ];
  const userPrize = prizePool[userPos - 1] || 50000000;

  // Find top scorer
  const topScorer = [...players].sort((a, b) => b.seasonGoals - a.seasonGoals)[0];
  const topClub = clubs.find((c) => c.id === topScorer?.clubId);

  const historyEntry: SeasonHistoryEntry = {
    seasonNumber: currentSeason,
    championClubId: champion.clubId,
    championClubName: champion.clubName,
    userPosition: userPos,
    userClubId,
    userClubName: clubs.find((c) => c.id === userClubId)?.name || 'Mi Club',
    topScorerName: topScorer?.name || 'Desconocido',
    topScorerGoals: topScorer?.seasonGoals || 0,
    topScorerClubName: topClub?.name || 'Liga',
    prizeMoneyYen: userPrize,
  };

  // Evolve players: Age + 1, growth or decline, contracts - 1, reset season stats
  const evolvedPlayers: Player[] = players.map((p) => {
    const age = p.age + 1;
    let growth = 0;

    if (age <= 21) {
      growth = Math.floor(Math.random() * 4) + 1; // Youngsters grow +1 to +4
    } else if (age <= 25) {
      growth = Math.floor(Math.random() * 3); // Prime ages grow 0 to +2
    } else if (age >= 32) {
      growth = -Math.floor(Math.random() * 3) - 1; // Decline -1 to -3
    }

    const newOvr = Math.min(99, Math.max(50, p.overall + growth));
    const newStats = { ...p.stats };
    Object.keys(newStats).forEach((k) => {
      const key = k as keyof Player['stats'];
      newStats[key] = Math.min(99, Math.max(30, newStats[key] + growth));
    });

    return {
      ...p,
      age,
      overall: newOvr,
      stats: newStats,
      fitness: 100,
      morale: 80,
      form: 75,
      contractYears: Math.max(0, p.contractYears - 1),
      injuryWeeks: 0,
      isBanned: false,
      yellowCardsCount: 0,
      seasonMatches: 0,
      seasonGoals: 0,
      seasonAssists: 0,
      seasonYellowCards: 0,
      seasonRedCards: 0,
      seasonCleanSheets: 0,
      seasonAverageRating: 6.8,
    };
  });

  // Update clubs with prize money and renewed budget
  const evolvedClubs: Club[] = clubs.map((c) => {
    const pos = table.findIndex((r) => r.clubId === c.id) + 1;
    const prize = prizePool[pos - 1] || 50000000;
    return {
      ...c,
      cashYen: c.cashYen + prize,
      budgetYen: Math.round(c.budgetYen * 0.9) + Math.round(prize * 0.7),
    };
  });

  const nextSeason = currentSeason + 1;
  const newFixtures = generateSeasonFixtures(nextSeason, evolvedClubs);

  return {
    newSeason: nextSeason,
    newClubs: evolvedClubs,
    newPlayers: evolvedPlayers,
    newFixtures,
    seasonHistoryEntry: historyEntry,
  };
}

